class Rewards extends StatelessWidget {
  const Rewards({super.key});
  @override
  Widget build(BuildContext c) => Pad([
    const Text('POINTS • MISSIONS • BENEFITS', style: TextStyle(fontSize: 10, letterSpacing: 1.2, fontWeight: FontWeight.w900, color: Color(0xFF828AA0))),
    const SizedBox(height: 7),
