      padding: const EdgeInsets.all(22),
      decoration: BoxDecoration(borderRadius: BorderRadius.circular(23), gradient: const LinearGradient(colors: [Color(0xFF121A39), Color(0xFF3A4FC0), purple])),
      child: const Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Icon(Icons.stars, color: Color(0xFFFFD77B), size: 31),
        SizedBox(height: 12),
        Text('0', style: TextStyle(fontSize: 39, fontWeight: FontWeight.w900, color: Colors.white)),
        Text('DEMO POINTS', style: TextStyle(color: Color(0xFFDCE2FF), fontSize: 10, letterSpacing: 1.5)),
        SizedBox(height: 10),
        Text('Points are not cash. No payout is active in preview.', style: TextStyle(color: Colors.white70, fontSize: 12)),
      ]),
    ),
    const Head('Ways to participate'),
    ...['Daily check-in', 'Missions & challenges', 'Leaderboard & badges', 'Points history', 'Rewards catalogue'].map((s) => RowAction(
      title: s, sub: 'Open ${s.toLowerCase()}', icon: Icons.stars,
      tap: () => open(c, Detail(title: s, icon: Icons.stars, items: s == 'Daily check-in'
        ? ['Daily streak preview', 'Rewards need server verification']
